{
  "decisions": [
    {
      "entity_path": "config/archive_format",
      "change_type": "reject",
      "reasoning": "We rejected zstd because the downstream importer cannot decode it. The importer accepts zip and gzip. Use gzip for the smallest compatible export until the importer gains zstd support.",
      "constraint": "Nightly archives must be decodable by the downstream importer.",
      "stale_when": "Downstream importer adds tested zstd support."
    }
  ],
  "note": "This file is independent of any connected memory server."
}

{
  "status": "applied",
  "key": "archive_format",
  "value": "zstd",
  "rationale": "zstd produces the smallest nightly exports at 6 MB, versus 9 MB for gzip and 12 MB for zip. It was previously rejected because the downstream importer lacked zstd support, but the decision record's own staleness condition has now been met: today's importer upgrade includes passing zstd decode compatibility tests across all three formats. With the compatibility blocker lifted, zstd is both a supported choice and the smallest available format."
}
